<template>
	<view :style="{ '--mobile-header-height': headerHeight + 'px' }" class="delivery-page" :class="{'login-page':screen==='login','compact-layout':['orders','messages','mine'].includes(screen)}">
		<MobileHeader ref="mobileHeader" @layout="headerHeight = $event" v-if="screen!=='login'&&screen!=='workbench'&&screen!=='alert'" :title="pageTitle" @back="goBack" />
		<view v-if="screen==='login'" class="login-screen"><image class="login-landscape" src="/static/design/spring-landscape.jpg" mode="aspectFill" aria-hidden="true"/><MobileHeader ref="mobileHeader" @layout="headerHeight = $event" :back="false" title="" transparent />
			<view class="login-brand"><image class="courier-mark" src="/static/spring-mark.svg" mode="aspectFit"/><text class="ui-strong">山泉配送</text><text>专注每一滴 · 服务每一单</text></view>
			<view class="login-form"><text class="integration-note">{{ appConfig.demoAuth ? '本地联调可使用演示账号；正式账号仍可使用密码登录' : '请使用后台分配的送水员手机号和密码登录' }}</text><view class="login-input"><AppIcon name="phone" size="30rpx" tone="muted"/><input v-model="phone" type="number" maxlength="11" placeholder="请输入已绑定手机号" /></view><view class="login-input"><AppIcon name="shield" size="30rpx" tone="muted"/><input v-model="password" :password="!passwordVisible" maxlength="64" placeholder="请输入登录密码" /><view class="password-eye" role="button" :aria-label="passwordVisible ? '隐藏密码' : '显示密码'" @click="passwordVisible=!passwordVisible"><AppIcon :name="passwordVisible ? 'eye' : 'eye-off'" size="32rpx" tone="muted"/></view></view><ConsentNotice :checked="authConsent" :disabled="loginLoading" @update:checked="authConsent = $event" courier /><button :disabled="loginLoading" @click="login">{{ loginLoading ? '正在验证…' : '登录工作台' }}</button></view>
			<button class="customer-home-button" :disabled="loginLoading" @click="openCustomerHome">返回客户首页</button>
			<view class="current-station"><text>所属水站</text><view><AppIcon name="pin" size="29rpx"/><text class="ui-strong">{{courierProfile.station || '登录后自动识别'}}</text></view></view>
		</view>

		<template v-else-if="screen==='workbench'||screen==='alert'">
			<view class="work-hero"><MobileHeader ref="mobileHeader" @layout="headerHeight = $event" :back="false" title="" dark transparent /><view class="work-profile"><view class="avatar">{{(courierProfile.name || '送').slice(0,1)}}</view><view><text class="ui-strong">{{courierProfile.name || '送水员'}}</text><text>{{courierProfile.station || '水站待同步'}}</text></view><view class="online"><text>{{updatingOnline ? '同步中' : online ? '接单中' : '已暂停接单'}}</text><switch :checked="online" :disabled="updatingOnline" color="#68d8bf" @change="toggleOnline"/></view></view></view>
			<scroll-view scroll-y class="work-scroll">
				<view class="stats-card"><view class="today"><text>今日已加载订单</text><text class="ui-strong">{{deliveryStats.total}}<text class="ui-small"> 单</text></text></view><view class="stat-grid"><view><text class="ui-strong">{{deliveryStats.pending}}</text><text>待配送</text></view><view><text class="ui-strong">{{deliveryStats.delivering}}</text><text>配送中</text></view><view><text class="ui-strong">{{deliveryStats.completed}}</text><text>已完成</text></view></view><view class="bar-stat"><text>今日已加载桶数</text><text class="ui-strong">{{deliveryStats.barrels}}<text class="ui-small"> 桶</text></text></view></view>
				<view class="list-note">待配送、配送中为全部任务；今日数字仅含已加载记录，非全天总计。</view>
				<view v-if="ordersError" class="list-note" role="alert">{{ordersError}}<button @click="loadOrders(true)">重试同步</button></view>
				<view class="section-row"><text class="ui-strong">下一单任务</text><text @click="loadOrders(true)">刷新</text></view>
				<view v-if="nextOrder" class="next-card" @click="selectOrder(nextOrder)"><view><text class="ui-strong">{{nextOrder.customer}}</text><text class="status-chip">{{nextOrder.status}}</text></view><text>{{nextOrder.address}}</text><text class="ui-strong">{{nextOrder.deliveryWindow || nextOrder.timeLabel}} <text class="ui-small">{{nextOrder.deliveryWindow ? '配送时段' : '下单'}}</text></text><view><text>{{nextOrder.orderType==='补送' ? '补送单 · ' : ''}}{{nextOrder.spec}} · {{nextOrder.courierId ? '已由后台派单' : '等待派单'}}</text><text>›</text></view></view>
				<view v-else class="next-card"><view><text class="ui-strong">暂无配送任务</text><text class="status-chip">{{ordersError?'同步失败':hasSyncedPending?'已同步':'同步中'}}</text></view><text>后台派单后会自动出现在这里</text></view>
				<view class="section-row"><text class="ui-strong">常用工具</text></view><view class="tools"><view @click="openTicketSign"><view class="tool-icon"><AppIcon name="ticket" size="31rpx" tone="light"/></view><text>上门收票</text></view><view @click="signNextOrder"><view class="tool-icon"><AppIcon name="check" size="31rpx" tone="light"/></view><text>主动签收</text></view><view @click="callCustomer"><view class="tool-icon"><AppIcon name="phone" size="31rpx" tone="light"/></view><text>联系客户</text></view><view @click="navigateToCustomer"><view class="tool-icon"><AppIcon name="map" size="31rpx" tone="light"/></view><text>导航到客户</text></view></view>
				<view class="section-row"><text class="ui-strong">今日已加载订单</text><text @click="navChange('orders')">全部订单 ›</text></view><view class="simple-order" v-for="o in todayOrders.slice(0,6)" :key="o.id" @click="selectOrder(o)"><view class="order-index">{{o.index}}</view><view><text class="ui-strong">{{o.customer}}</text><text>{{o.address}}</text></view><view><text class="ui-strong">{{o.timeLabel}}</text><text>{{o.status}}</text></view></view>
				<view v-if="!todayOrders.length" class="simple-order"><view class="order-index">–</view><view><text class="ui-strong">已加载记录中无今日订单</text><text>全部任务已同步，历史记录可在订单页加载</text></view></view>
				<view class="nav-spacer" aria-hidden="true"/>
			</scroll-view>
			<BottomNav active="workbench" variant="delivery" :badge="activeOrderCount" @change="navChange"/>
			<view v-if="screen==='alert'" class="alert-layer"><view class="alert-card"><view class="bell"><AppIcon name="bell" size="50rpx" tone="light"/></view><text class="ui-strong">新订单已派送给您</text><text>请及时处理</text><view class="alert-info"><view><text>客户</text><text class="ui-strong">{{pendingOrder?.customer || '同步中'}}</text><AppIcon name="phone" size="26rpx"/></view><view><text>地址</text><text class="ui-strong">{{pendingOrder?.address || '同步中'}}</text></view><view><text>商品</text><text class="ui-strong">{{pendingOrder?.spec || '同步中'}}</text></view><view><text>订单号</text><text class="ui-strong">{{pendingOrder?.id || '同步中'}}</text><AppIcon name="pin" size="25rpx"/></view></view><button :disabled="alertAccepting||!pendingOrder" @click="acceptOrder">{{alertAccepting?'正在核验接单…':'立即接单'}}</button><text class="later" @click="dismissAlert">稍后处理（{{countdown}}s）</text></view></view>
		</template>

		<template v-else-if="screen==='orders'||screen==='messages'||screen==='mine'">
			<view class="work-hero compact"><view class="work-profile"><view class="avatar">{{(courierProfile.name || '送').slice(0,1)}}</view><view><text class="ui-strong">{{ {orders:'我的订单',messages:'消息动态',mine:'我的'}[screen] }}</text><text>{{courierProfile.name || '送水员'}} · {{courierProfile.station || '水站待同步'}}</text></view></view></view>
			<scroll-view scroll-y class="work-scroll">
				<template v-if="screen==='orders'">
					<view class="segment-row"><text v-for="tab in orderTabs" :key="tab" :class="{active:orderTab===tab}" @click="setOrderTab(tab)">{{tab}}</text></view>
					<view class="simple-order" v-for="o in filteredOrders" :key="o.id" @click="selectOrder(o)"><view class="order-index">{{o.index}}</view><view><text class="ui-strong">{{o.customer}} · {{o.spec}}</text><text>{{o.address}}</text></view><view><text class="ui-strong">{{o.deliveryWindow || o.timeLabel}}</text><text>{{o.status}}</text></view></view>
					<view v-if="!filteredOrders.length" class="simple-order"><view class="order-index">–</view><view><text class="ui-strong">暂无{{orderTab==='全部'?'':orderTab}}订单</text><text>数据每 3 秒自动同步</text></view></view>
				</template>
				<template v-else-if="screen==='messages'">
					<view class="list-note">显示已加载订单中最近 30 条动态；可继续加载历史订单。</view>
					<view class="simple-order" v-for="m in messages" :key="m.key"><view class="order-index"><AppIcon name="bell" size="26rpx" tone="light"/></view><view><text class="ui-strong">{{m.title}}</text><text>{{m.orderId}} · {{m.customer}}</text></view><view><text class="ui-strong">{{m.time}}</text><text>{{m.status}}</text></view></view>
					<view v-if="!messages.length" class="simple-order"><view class="order-index">–</view><view><text class="ui-strong">暂无消息</text><text>派单、接单、签收都会记录在这里</text></view></view>
				</template>
				<template v-else>
					<view class="list-note">今日完成及桶数仅含已加载记录，非全天总计；待配送、配送中为全部任务。</view>
					<view class="stats-card"><view class="today"><text>今日已加载完成</text><text class="ui-strong">{{deliveryStats.completed}}<text class="ui-small"> 单</text></text></view><view class="stat-grid"><view><text class="ui-strong">{{deliveryStats.pending}}</text><text>待配送</text></view><view><text class="ui-strong">{{deliveryStats.delivering}}</text><text>配送中</text></view><view><text class="ui-strong">{{deliveryStats.barrels}}</text><text>桶数</text></view></view></view>
					<view class="mine-list"><view><text>姓名</text><text class="ui-strong">{{courierProfile.name || '送水员'}}</text></view><view><text>手机号</text><text class="ui-strong">{{courierProfile.phone || phone || '--'}}</text></view><view><text>所属水站</text><text class="ui-strong">{{courierProfile.station || '水站待同步'}}</text></view><view><text>接单提醒</text><text class="ui-strong">{{online ? '开启' : '已暂停'}}</text></view></view>
					<button class="customer-home-button" @click="openCustomerHome">返回客户首页</button>
					<view class="courier-legal-links"><navigator url="/pages/legal/index?type=terms">用户服务协议</navigator><navigator url="/pages/legal/index?type=privacy">隐私政策</navigator></view>
					<button class="password-button" @click="changePassword">修改登录密码</button><button class="logout-button" @click="logout">退出登录</button>
				</template>
				<view v-if="screen==='orders'||screen==='messages'" class="list-pagination">
					<text v-if="ordersError" role="alert">{{ordersError}}</text>
					<button v-if="ordersError" :disabled="ordersLoading" @click="loadOrders(true)">重试同步</button>
					<template v-if="screen==='messages'||!['待配送','配送中'].includes(orderTab)"><text>历史列表已加载 {{historyOrders.length}} / {{historyTotal}} 单</text><button v-if="historyHasMore" :disabled="loadingMore" @click="loadMoreOrders">{{ordersLoading||loadMorePending?'加载中…':'加载更多历史订单'}}</button></template>
					<text v-else>全部{{orderTab}}任务（含暂停任务） {{filteredOrders.length}} 单</text>
				</view>
				<view class="nav-spacer" aria-hidden="true"/>
			</scroll-view>
			<BottomNav :active="screen" variant="delivery" :badge="activeOrderCount" @change="navChange"/>
		</template>

		<scroll-view v-else-if="screen==='delivery-detail'" scroll-y class="detail-scroll">
			<view v-if="selectionError" class="detail-card note" role="alert"><text>{{selectionError}}</text><button @click="open('orders')">返回任务列表</button></view><view class="delivery-state"><view class="clock"><AppIcon name="clock" size="35rpx" tone="light"/></view><view><text class="ui-strong">{{activeOrder?.status || '订单不可操作'}}</text><text>{{activeOrder?.dispatchStatus || '订单状态实时同步'}}</text></view></view>
			<view class="detail-card customer"><view><text>客户</text><text class="ui-strong">{{activeOrder?.customer || '暂无客户'}}</text><text>{{activeOrder?.phone || '--'}}</text></view><button @click="callCustomer"><AppIcon name="phone" size="32rpx"/></button></view>
			<view class="detail-card address-block"><view><text>地址</text><text class="ui-strong">{{activeOrder?.address || '暂无地址'}}</text><text v-if="activeOrder?.deliveryWindow" class="ui-small">配送时段 {{activeOrder.deliveryWindow}}</text></view><button aria-label="导航到客户地址" @click="navigateToCustomer"><AppIcon name="pin" size="30rpx"/><text class="ui-small">导航</text></button></view>
			<view class="detail-card"><text class="block-title">商品{{activeOrder?.orderType==='补送' ? '（售后补送单）' : ''}}</text><view class="product-line" v-for="line in activeLines" :key="line.lineNo"><WaterJug size="small" :label="line.product" :spec="line.spec"/><view><text class="ui-strong">{{line.product}}</text><text>{{line.spec}} × {{line.quantity}}{{line.ticketQuantity ? `（水票抵 ${line.ticketQuantity}）` : ''}}</text></view></view><view class="recycle"><text class="ui-span">配送数量</text><text class="ui-strong">× {{activeOrder?.quantity || 0}}</text></view><view class="recycle"><text class="ui-span">{{receivable.label}}</text><text class="ui-strong">{{receivable.value}}</text></view></view>
			<view v-if="activeOrder?.fulfillmentHoldReason" class="detail-card note"><text>暂停配送</text><text>{{activeOrder.fulfillmentHoldReason}}</text></view><view v-else-if="activeOrder?.status==='待配送'" class="detail-card note"><text>尚未接单</text><text class="ui-strong">点击下方“接单并开始配送”后，客户端才会出现签收码，也才能上门收票</text></view>
			<view class="detail-card note"><text>备注</text><text class="ui-strong">{{activeOrder?.remark || '无特殊备注'}}</text></view>
		</scroll-view>

		<scroll-view v-else-if="screen==='sign'" scroll-y class="detail-scroll sign-scroll">
			<view v-if="activeOrder" class="detail-card sign-target"><text class="block-title">本次签收订单（请核对）</text><view class="recycle"><text class="ui-span">订单号</text><text class="ui-strong">{{activeOrder.id}}</text></view><view class="recycle"><text class="ui-span">客户</text><text class="ui-strong">{{activeOrder.customer || '--'}} {{activeOrder.phone || ''}}</text></view><view class="recycle"><text class="ui-span">地址</text><text class="ui-strong">{{activeOrder.address || '--'}}</text></view><view class="recycle"><text class="ui-span">{{receivable.label}}</text><text class="ui-strong">{{receivable.value}}</text></view></view><view v-else class="detail-card note sign-target"><text class="ui-strong">未选择签收订单</text><text>请返回工作台或订单列表，选择要签收的订单</text></view>
			<text class="sign-label">选择签收方式</text><view class="sign-options"><view v-for="item in signOptions" :key="item.id" :class="{active:signMethod===item.id,unavailable:!item.available}" @click="item.available&&(signMethod=item.id)"><view class="sign-icon"><AppIcon :name="item.icon" size="30rpx"/></view><view><text class="ui-strong">{{item.name}}</text><text class="ui-small">{{item.note}}</text></view><text class="ui-span">{{signMethod===item.id?'✓':''}}</text></view></view>
			<view v-if="signMethod==='ticket'" class="ticket-form"><text class="sign-label">上门回收客户水票</text><view class="segment-row"><text :class="{active:ticketType==='纸质票'}" @click="ticketType='纸质票'">纸质票</text><text :class="{active:ticketType==='电子票'}" @click="ticketType='电子票'">电子票</text></view><view class="ticket-input"><input v-model="ticketCode" placeholder="输入水票编码，如 JT000238 / ET0001" confirm-type="done" @confirm="addTicket" /><button aria-label="扫码录入水票" @click="scanTicketCode"><AppIcon name="qr" size="26rpx" tone="light"/></button></view><button class="add-ticket" :disabled="ticketChecking" @click="addTicket">{{ticketChecking ? '校验中…' : '添加这张水票'}}</button><view v-for="(item,index) in collectTickets" :key="item.type + item.code" class="ticket-chip"><text>{{item.type}} {{item.code}}</text><text class="remove-ticket" @click="removeTicket(index)">移除</text></view><text class="ui-small">{{ticketPreview ? `收 ${collectTickets.length} 张水票后应收 ¥${Number(ticketPreview.amount).toFixed(2)}（水票抵 ¥${Number(ticketPreview.ticketAmount).toFixed(2)}）` : '每张水票抵一桶，签收时核销；差额当面收取'}}</text><text class="ui-small ticket-rule">仅可回收水站已发放给该客户的水票；未发放的纸质票需先由水站在后台发放</text></view>
			<view v-if="signMethod==='scan'" class="ticket-form"><text class="sign-label">扫描客户签收二维码</text><view class="ticket-input"><input v-model="receiptCode" type="number" maxlength="6" placeholder="扫描或输入 6 位签收码" /><button @click="scanReceiptCode"><AppIcon name="qr" size="26rpx" tone="light"/></button></view><text class="ui-small">签收码仅对该订单有效，服务端校验通过后才会完成签收</text></view>
			<text class="sign-label">送达凭证（可选，上传后随订单保存并同步给客户）</text><view class="proof-photo"><image v-if="proofLocalPath" :src="proofLocalPath" mode="aspectFill"/><view v-else class="proof-empty" @click="chooseProof"><AppIcon name="camera" size="54rpx" tone="muted"/><text>拍摄或上传送达照片</text><text class="ui-small">上传后，客户可在订单中查看</text></view><view class="retake" @click="chooseProof"><AppIcon name="camera" size="24rpx" tone="light"/><text>{{proofLocalPath?'重新拍照':'选择照片'}}</text></view></view><view class="confirm-check" @click="confirmed=!confirmed"><text class="ui-span" :class="{on:confirmed}">{{confirmed?'✓':''}}</text><text>已核对以上订单，并与客户确认完成送达</text></view>
		</scroll-view>

		<scroll-view v-else scroll-y class="detail-scroll"><view class="detail-card note"><text class="ui-strong">页面不存在</text><text>该入口已下线，请返回工作台继续配送</text><button class="add-ticket" @click="open('workbench')">返回工作台</button></view></scroll-view>

		<view v-if="screen==='delivery-detail'" class="double-action"><button class="ghost" @click="callCustomer">☎ 联系客户</button><button v-if="canAcceptSelected" :disabled="accepting" @click="acceptSelectedOrder">{{ accepting ? '正在接单…' : '接单并开始配送' }}</button><button v-else-if="activeOrder?.status==='配送中'&&!activeOrder?.fulfillmentHoldReason" @click="open('sign')">确认送达</button><button v-else disabled>{{ activeOrder?.fulfillmentHoldReason ? '暂停配送' : (activeOrder?.status || '暂无订单') }}</button></view>
		<view v-else-if="screen==='sign'" class="single-action"><button :disabled="signing||!activeOrder" @click="finishSign">{{ signing ? '正在签收…' : (signMethod==='ticket' ? '收票并签收' : '确认签收') }}</button></view>
	</view>
</template>

<script>
import ConsentNotice from '../../components/ConsentNotice.vue'
import { CONSENT_MESSAGE, rememberConsent } from '../../services/privacy.js'
import MobileHeader from '../../components/MobileHeader.vue'
import BottomNav from '../../components/BottomNav.vue'
import WaterJug from '../../components/WaterJug.vue'
import AppIcon from '../../components/AppIcon.vue'
import { waterApi } from '../../services/waterApi.js'
import { compressIfLarge } from '../../services/imageFiles.js'

export default {
	components:{ConsentNotice,MobileHeader,BottomNav,WaterJug,AppIcon},
	data(){return{ headerHeight: 44, readRevisions: {}, readEpoch: 0, screen:'login',phone:'',password:'',loginLoading:false,authConsent:false,passwordVisible:false,appConfig:{demoAuth:false},countdown:15,countdownTimer:null,signMethod:'manual',confirmed:false,proofLocalPath:'',signing:false,accepting:false,ticketType:'纸质票',ticketCode:'',collectTickets:[],ticketPreview:null,ticketChecking:false,receiptCode:'',online:false,updatingOnline:false,orderTab:'全部',orderTabs:['全部','待配送','配送中','已完成'],refreshTimer:null,selectedOrder:null,knownPendingIds:[],courierProfile:{id:'',name:'',station:'',phone:''},
		activeOrders:[],historyOrders:[],unavailableOrderIds:{},historyPage:0,historyTotal:0,historyPageSize:20,ordersLoading:false,ordersError:'',selectionError:'',ordersRevision:0,ordersReloadPending:false,loadMorePending:false,loadingMore:false,hasSyncedPending:false,pendingAlertIds:[],alertRevision:0,alertAccepting:false,selectionRevision:0,pageDisposed:false
	}},
	computed:{
		orders(){const rows=new Map(this.historyOrders.map(order=>[order.id,order]));for(const order of this.activeOrders)rows.set(order.id,order);return [...rows.values()]},
		historyHasMore(){return this.historyPage*this.historyPageSize<this.historyTotal},
		pageTitle(){return{'delivery-detail':'配送单详情',sign:this.signMethod==='ticket'?'上门收票签收':this.signMethod==='scan'?'扫码签收':'主动签收'}[this.screen]||''},
		/** 上门收票只适用于配送中、未付款的货到付款订单（已付款订单收票会重复收费；未接单时服务端拒绝收票） */
		ticketSignAvailable(){const order=this.activeOrder;return Boolean(order)&&order.status==='配送中'&&order.orderType!=='补送'&&order.payment==='货到付款'&&order.payStatus==='未支付'},
		signOptions(){const delivering=this.activeOrder?.status==='配送中';return [{id:'manual',icon:'camera',name:'送水员主动签收',note:'由送水员手动确认送达',available:true},{id:'ticket',icon:'ticket',name:'上门收票签收',note:this.ticketSignAvailable?'回收客户纸质票/电子票抵扣应收，差额当面收取':delivering?'仅未付款的货到付款订单可收票':'请先接单开始配送，再上门收票',available:this.ticketSignAvailable},{id:'scan',icon:'qr',name:'扫描签收码',note:delivering?'扫描客户订单详情中的签收二维码':'接单开始配送后，客户端才会出现签收码',available:delivering}]},
		/** 详情页的接单入口：派给本人的待配送任务（含首次同步前派单、稍后处理、暂停期间派单的任务） */
		canAcceptSelected(){const order=this.selectedOrder;return this.screen==='delivery-detail'&&Boolean(order)&&!this.unavailableOrderIds[order.id]&&order.status==='待配送'&&!order.fulfillmentHoldReason&&(!order.courierId||!this.courierProfile.id||order.courierId===this.courierProfile.id)},
		activeLines(){const order=this.activeOrder;if(!order)return [];if(Array.isArray(order.items)&&order.items.length)return order.items;return [{lineNo:1,product:order.product,spec:order.spec,quantity:order.quantity,ticketQuantity:0}]},
