		messages(){const labels={seed:'历史订单',create:'客户下单',pay:'客户已支付','pay-balance':'客户余额支付','pay-wechat':'客户微信支付','pay-ticket':'水票全额抵扣','confirm-cod':'货到付款已确认',assign:'后台派单给你',accept:'你已接单','collect-tickets':'上门收取水票',complete:'签收完成','cod-collected':'货到付款已收款',cancel:'订单已取消','auto-cancel':'超时未支付关闭','create-replacement':'售后补送单','replacement-created':'已生成售后补送单','refund-stop-delivery':'退款停止配送','return-hold-delivery':'退货暂停配送','confirm-receipt':'客户已确认收货','late-payment-refund-pending':'超时到账款待退回','late-payment-refunded':'超时到账款已退回',unassign:'后台已撤回派单'};const list=[];for(const order of this.orders){for(const event of order.timeline||[]){list.push({key:`${order.id}-${event.at}-${event.action}`,orderId:order.id,customer:order.customer,title:labels[event.action]||'订单动态更新',status:event.status,at:event.at,time:this.formatTime(event.at)})}}return list.sort((a,b)=>String(b.at).localeCompare(String(a.at))).slice(0,30)}},
