	onLoad(query){if(query&&query.screen)this.screen=query.screen==='call'?'workbench':query.screen;waterApi.getConfig().then(config=>{this.appConfig=config});if(this.screen!=='login'){if(waterApi.hasSession('courier'))this.syncCourierProfile().then(()=>this.startSync()).catch(error=>{if(error.code==='STALE_SESSION'||this.pageDisposed)return;if([401,403].includes(error.statusCode))waterApi.clearLocalSession('courier');this.open('login');this.toast(error.message)});else this.screen='login'}if(this.screen==='alert')this.screen='workbench'},
