		toast(title){if(waterApi.recentlyToasted?.(title))return;uni.showToast({title,icon:'none'})},formatTime(value){const date=new Date(value);return Number.isNaN(date.getTime())?'--:--':`${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')} ${String(date.getHours()).padStart(2,'0')}:${String(date.getMinutes()).padStart(2,'0')}`},
		async login(){if(this.loginLoading)return;if(!this.authConsent)return this.toast(CONSENT_MESSAGE);if(!/^1[3-9]\d{9}$/.test(this.phone))return this.toast('请输入 11 位已绑定手机号');this.loginLoading=true;try{try{rememberConsent('courier')}catch{throw new Error('无法保存授权状态，请检查设备存储后重试')}this.appConfig=await waterApi.getConfig();if(!this.appConfig.demoAuth&&this.password.length<6)throw new Error('请输入至少 6 位登录密码');const session=this.appConfig.demoAuth&&!this.password?await waterApi.login('courier',{phone:this.phone},true):await waterApi.loginWithPassword('courier',this.phone,this.password);this.courierProfile=session.profile||this.courierProfile;this.password='';this.passwordVisible=false;await this.syncCourierProfile();await this.loadOrders();this.open('workbench')}catch(error){this.showLoginError(error)}finally{this.loginLoading=false}},
		/** 登录被拒时用弹窗显示完整原因（真机 toast 会截断长文字）；密码里有中文、全角或空格时多给一句可操作的提示 */
		showLoginError(error){const message=error?.message||'暂时无法登录，请稍后重试';if(error?.statusCode!==401)return this.toast(message);const hint=/[^!-~]/.test(this.password)?'\n密码里含有中文、全角或空格字符，请点右侧眼睛图标核对，切换到英文键盘后重新输入。':'';uni.showModal({title:'无法登录',content:message+hint,showCancel:false})},
