		resetCourierSession(){this.authConsent=false;this.invalidateReads();this.unavailableOrderIds={};this.selectionError='';this.selectionRevision++;this.setAlertQueue([]);this.alertRevision++;this.ordersRevision++;this.ordersReloadPending=false;this.activeOrders=[];this.historyOrders=[];this.historyPage=0;this.historyTotal=0;this.ordersError='';this.selectedOrder=null;this.knownPendingIds=[];this.hasSyncedPending=false;this.courierProfile={id:'',name:'',station:'',phone:''};this.open('login')},
