		startSync(){this.stopSync();this.loadOrders();this.refreshTimer=setInterval(()=>this.loadOrders(),3000)},stopSync(){if(this.refreshTimer){clearInterval(this.refreshTimer);this.refreshTimer=null}},selectOrder(order){if(!order||this.unavailableOrderIds[order.id])return this.toast('该订单已不可访问，请刷新任务列表');this.selectionError='';this.selectionRevision++;this.selectedOrder=order;this.open('delivery-detail')},
