		resetTickets(){this.collectTickets=[];this.ticketPreview=null;this.ticketCode=''},
		/** 录入一张水票并向服务端试算收票后的应收；校验失败的票不会加入 */
		async addTicket(){const code=this.ticketCode.trim().toUpperCase();if(!code)return this.toast('请输入或扫描水票编码');if(this.collectTickets.some(item=>item.code===code))return this.toast('这张水票已添加');const order=this.activeOrder;if(!order)return this.toast('暂无可签收订单');if(!this.ticketSignAvailable)return this.toast(order.status!=='配送中'?'请先接单开始配送，再上门收票':'仅未付款的货到付款订单可收票');const next=[...this.collectTickets,{type:this.ticketType,code}];this.ticketChecking=true;try{this.ticketPreview=await waterApi.courierPreviewTickets({orderId:order.id,tickets:next});this.collectTickets=next;this.ticketCode=''}catch(error){this.toast(error.message)}finally{this.ticketChecking=false}},
