			const url=hasCoords?`https://uri.amap.com/marker?position=${lng},${lat}&name=${encodeURIComponent(order.address||'收货地址')}&coordinate=gaode&callnative=1`:`https://uri.amap.com/search?keyword=${encodeURIComponent(order.address||'')}&callnative=1`
			if(typeof window!=='undefined'&&typeof window.open==='function')window.open(url,'_blank');else this.copyAddress(order)},
		copyAddress(order){if(!order?.address)return this.toast('订单没有收货地址');uni.setClipboardData({data:order.address,success:()=>uni.showModal({title:'地址已复制',content:'该订单暂无定位坐标，已复制收货地址，可粘贴到地图 App 中导航。',showCancel:false}),fail:()=>uni.showModal({title:'收货地址',content:order.address,showCancel:false})})},
		scanReceiptCode(){if(typeof uni.scanCode!=='function')return this.toast('当前环境不支持扫码，请手动输入');uni.scanCode({scanType:['qrCode'],success:result=>{this.receiptCode=String(result.result||'').replace(/\D/g,'').slice(-6)},fail:error=>{if(!/cancel/i.test(String(error&&error.errMsg)))this.toast('扫码失败，请手动输入')}})},
		callCustomer(){const phone=String(this.activeOrder?.phone||'').replace(/\D/g,'');if(phone.length!==11||typeof uni.makePhoneCall!=='function')return this.toast('订单没有可直接拨打的完整手机号');uni.makePhoneCall({phoneNumber:phone,fail:error=>{if(!/cancel/i.test(String(error&&error.errMsg)))this.toast('拨号失败')}})},
		chooseProof(){if(typeof uni.chooseImage!=='function')return this.toast('当前环境不支持选择照片');uni.chooseImage({count:1,sizeType:['compressed'],sourceType:['camera','album'],success:result=>{compressIfLarge(result.tempFilePaths?.[0]||'',result.tempFiles?.[0]?.size).then(path=>{this.proofLocalPath=path})},fail:error=>{if(!/cancel/i.test(String(error&&error.errMsg)))this.toast('照片选择失败')}})},
		isCurrentActiveSelection(id,revision){return !this.pageDisposed&&this.selectionRevision===revision&&this.activeOrder?.id===id},
		async finishSign(){if(this.signing)return;const target=this.screen==='sign'?this.selectedOrder:null;if(!target)return this.toast('请先从任务列表选择要签收的订单');if(!this.confirmed)return this.toast('请核对订单信息并勾选“已完成送达”');if(target.fulfillmentHoldReason)return this.toast(target.fulfillmentHoldReason);if(this.signMethod!=='manual'&&target.status!=='配送中')return this.toast(this.signMethod==='ticket'?'请先接单开始配送，再上门收票':'请先接单开始配送，客户端出现签收码后再扫码签收');if(this.signMethod==='ticket'&&!this.ticketSignAvailable)return this.toast('已付款订单不能再收水票，请选择其他签收方式');if(this.signMethod==='ticket'&&!this.collectTickets.length)return this.toast('请先添加要回收的水票');if(this.signMethod==='scan'&&!/^\d{6}$/.test(this.receiptCode.trim()))return this.toast('请输入或扫描 6 位签收码');const targetId=target.id,revision=this.selectionRevision;this.signing=true;try{let order=target;if(order.status==='待配送')order=await waterApi.acceptOrder(order.id);if(!this.isCurrentActiveSelection(targetId,revision))return;if(order.status!=='配送中')return this.toast('仅配送中订单可签收');let proofUrl='';if(this.proofLocalPath){const uploaded=await waterApi.uploadImage(this.proofLocalPath,'courier');proofUrl=uploaded.url}if(!this.isCurrentActiveSelection(targetId,revision))return;const payload={signMethod:this.signMethod,proofUrl:proofUrl||undefined};if(this.signMethod==='ticket')payload.tickets=this.collectTickets;if(this.signMethod==='scan')payload.receiptCode=this.receiptCode.trim();const updated=await waterApi.completeOrder(order.id,payload);if(!this.isCurrentActiveSelection(targetId,revision))return;const committedRevision=++this.selectionRevision;this.selectedOrder=this.mapOrder(updated,0);this.proofLocalPath='';this.resetTickets();this.receiptCode='';this.confirmed=false;this.toast(this.signMethod==='ticket'?`水票已核销，签收完成，应收 ¥${Number(updated.amount||0).toFixed(2)}`:this.signMethod==='scan'?'签收码校验通过，签收完成':'签收完成，三端状态已同步');this.signMethod='manual';await this.loadOrders();setTimeout(()=>{if(this.isCurrentActiveSelection(targetId,committedRevision))this.open('workbench')},600)}catch(error){if(this.isCurrentActiveSelection(targetId,revision))this.toast(error.message)}finally{this.signing=false}},
		navChange(name){if(['workbench','orders','messages','mine'].includes(name))this.open(name)},
	}
}
</script>

